create or replace function ml_private.allocate_spawns(v text,ids jsonb,s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare profile jsonb:=ml_private.version_catalog(v); id text; region text; groups integer; candidates jsonb; used jsonb:='[]'; cells jsonb:='[]'; cell jsonb; begin
 perform ml_private.need(v='web-v0.1.4','旧版使用固定坐标出生');
 perform ml_private.need(jsonb_typeof(ids)='array' and jsonb_array_length(ids)=4 and (select count(distinct x) from ml_private.arr(ids) x)=4,'必须有四个不同角色');
 for id in select x#>>'{}' from ml_private.arr(ids) x loop
  candidates:=ml_private.spawn_candidates(v,id); region:=profile#>>array['sourceCatalog','characters',id,'spawnRegion'];
  select count(*) into groups from ml_private.arr(ids) x where profile#>>array['sourceCatalog','characters',x#>>'{}','spawnRegion']=region;
  perform ml_private.need(jsonb_array_length(candidates)>0 and groups<=jsonb_array_length(candidates),'出生地区空格不足');
 end loop;
 for id in select x#>>'{}' from ml_private.arr(ids) x loop
  select jsonb_agg(x) into candidates from ml_private.arr(ml_private.spawn_candidates(v,id)) x where not used @> jsonb_build_array(x);
  s:=ml_private.int(s,jsonb_array_length(candidates)); cell:=candidates->(s->>'_int')::int;
  used:=used||jsonb_build_array(cell); cells:=cells||jsonb_build_array(cell); s:=s-'_int';
 end loop;
 return s||jsonb_build_object('_spawns',cells);
end $$;
-- Source for 012; existing installed migrations remain immutable.
create or replace function ml_private.classic_water(s jsonb,cell text) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(ml_private.game_data(s,'map')->cell->>'terrain'='water',false) $$;
create or replace function ml_private.classic_native(s jsonb,a integer) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce((ml_private.version_catalog(s->>'version')#>>array['characterTraits',s->'players'->a->>'character','waterNative'])::boolean,false) $$;
create or replace function ml_private.classic_enter(s jsonb,cell text) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select ml_private.game_data(s,'map') ? cell and not (coalesce((s#>>'{classic,farmClosed}')::boolean,false) and ml_private.region_at(s->>'version',cell)='高唐农场') $$;
create or replace function ml_private.classic_relocated(s jsonb,a integer,origin text,cell text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version'='web-v0.1.4' and ml_private.region_at(s->>'version',origin)<>ml_private.region_at(s->>'version',cell) then s:=jsonb_set(s,array['classic','exposure',a::text],jsonb_build_object('region',null,'streak',0)); end if; return s;
end $$;
create or replace function ml_private.classic_owes_water(s jsonb,a integer,origin text default null) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select s->>'version'='web-v0.1.4' and not ml_private.classic_native(s,a) and ml_private.classic_water(s,s->'players'->a->>'cell') and (origin is null or not ml_private.classic_water(s,origin)) and (s->'players'->a->>'hp')::int>0 and jsonb_array_length(s->'players'->a->'hand')>0 $$;
create or replace function ml_private.classic_pick(s jsonb,pool jsonb,amount integer,scripted boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare selected jsonb:='[]'; item jsonb; idx integer; begin
 while jsonb_array_length(pool)>0 and jsonb_array_length(selected)<amount loop
  if scripted and jsonb_array_length(s#>'{random,bombs}')>0 then item:=s#>'{random,bombs,0}'; s:=jsonb_set(s,'{random,bombs}',(s#>'{random,bombs}')-0); select ordinality::int-1 into idx from jsonb_array_elements(pool) with ordinality where value=item; perform ml_private.need(idx is not null,'注入轰炸地区无效或重复');
  else s:=ml_private.int(s,jsonb_array_length(pool)); idx:=(s->>'_int')::int; s:=s-'_int'; item:=pool->idx; end if;
  selected:=selected||jsonb_build_array(item); pool:=pool-idx;
 end loop; return s||jsonb_build_object('_picked',selected);
end $$;
create or replace function ml_private.classic_refresh(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare pool jsonb; safe jsonb; begin
 select coalesce(jsonb_agg(key),'[]') into pool from jsonb_each(ml_private.version_catalog(s->>'version')#>'{mapDefinition,regions}') where value->>'exposure'='indoor' and not (s#>'{classic,poison}' ? key);
 -- JSONB object iteration sorts keys; use map first-occurrence order to match TS.
 select coalesce(jsonb_agg(q.region order by q.first_cell),'[]') into pool from (select c->>'region' region,min(ord) first_cell from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality t(c,ord) where pool ? (c->>'region') group by c->>'region') q;
 s:=ml_private.classic_pick(s,pool,2); s:=jsonb_set(s,'{classic,poison}',(s#>'{classic,poison}')||(s->'_picked')); s:=s-'_picked';
 s:=jsonb_set(s,'{classic,farmClosed}',to_jsonb((s->>'round')::int>=5)); s:=jsonb_set(s,'{classic,bombs}','[]');
 select coalesce(jsonb_agg(c->'id'),'[]') into safe from ml_private.arr(ml_private.game_data(s,'cells')) c where not (s#>'{classic,poison}' ? (c->>'region'));
 return s||jsonb_build_object('safe',safe,'bomb',null,'forecast',null);
end $$;
create or replace function ml_private.classic_environment(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare pool jsonb; hits jsonb:='[]'; p jsonb; a integer; region text; old jsonb; danger boolean; streak integer; amount integer; loss integer; begin
 select jsonb_agg(q.region order by q.first_cell) into pool from (select c->>'region' region,min(ord) first_cell from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality t(c,ord) where ml_private.version_catalog(s->>'version')#>>array['mapDefinition','regions',c->>'region','exposure']='outdoor' group by c->>'region') q;
 s:=ml_private.classic_pick(s,pool,2,true);s:=jsonb_set(s,'{classic,bombs}',s->'_picked');s:=s-'_picked';
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int<=0 then continue; end if;
  region:=ml_private.region_at(s->>'version',p->>'cell');old:=s#>array['classic','exposure',a::text];danger:=s#>'{classic,poison}' ? region or s#>'{classic,bombs}' ? region;
  streak:=case when not danger then 0 when old->>'region'=region then (old->>'streak')::int+1 else 1 end;
  amount:=case when danger then power(2,least(30,streak-1))::int else 0 end;loss:=least((p->>'hp')::int,greatest(0,amount-(p->>'shield')::int));
  s:=jsonb_set(s,array['classic','exposure',a::text],case when loss>0 then jsonb_build_object('region',region,'streak',streak) else jsonb_build_object('region',null,'streak',0) end);
  hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',amount,'source',null,'category','environment'));
 end loop;return s||jsonb_build_object('_hits',hits);
end $$;
create or replace function ml_private.classic_landings(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare origin jsonb; cell jsonb; nearc jsonb; dr integer; dc integer; r integer; coln integer; result jsonb:='[]'; begin
 if s->>'version'<>'web-v0.1.4' or not ml_private.classic_native(s,a) then return '[]'; end if;
 origin:=ml_private.game_data(s,'map')->(s->'players'->a->>'cell');if origin->>'terrain'<>'land' then return '[]'; end if;
 for dr,dc in select * from (values(1,0),(-1,0),(0,1),(0,-1)) d(x,y) loop
  r:=(origin->>'row')::int+dr;coln:=(origin->>'col')::int+dc;cell:=ml_private.game_data(s,'map')->('r'||r||'c'||coln);if cell->>'terrain' is distinct from 'water' then continue; end if;
  while cell->>'terrain'='water' loop r:=r+dr;coln:=coln+dc;cell:=ml_private.game_data(s,'map')->('r'||r||'c'||coln);end loop;
  if cell is null then continue;end if;
  if ml_private.classic_enter(s,cell->>'id') and not ml_private.occupied(s,cell->>'id',-1) then result:=result||jsonb_build_array(cell->'id');
  elsif ml_private.occupied(s,cell->>'id',-1) then
   for nearc in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop if nearc->>'terrain'='land' and ml_private.distance_for_version(s->>'version',cell->>'id',nearc->>'id')=1 and ml_private.classic_enter(s,nearc->>'id') and not ml_private.occupied(s,nearc->>'id',-1) then result:=result||jsonb_build_array(nearc->'id');end if;end loop;
  end if;
 end loop;
 return (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where result ? (c->>'id'));
end $$;
create or replace function ml_private.classic_step_cost(s jsonb,a integer,cell text) returns integer language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 if not ml_private.classic_enter(s,cell) then return null;end if;
 if ml_private.classic_landings(s,a) ? cell then return 1;end if;
 if ml_private.distance_for_version(s->>'version',s->'players'->a->>'cell',cell)=1 then return case when ml_private.classic_water(s,cell) then 2 else 1 end;end if;return null;
end $$;
create or replace function ml_private.classic_walk(s jsonb,path jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int; p jsonb:=s->'players'->a; m jsonb:=s->'movement'; cell text; origin text; cost integer; idx integer:=0; check_s jsonb; begin
 s:=jsonb_set(s,'{phase}','"moving"');
 check_s:=s;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop
  perform ml_private.need(ml_private.legal_steps(check_s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');
  cost:=ml_private.classic_step_cost(check_s,a,cell);check_s:=jsonb_set(check_s,'{movement,remaining}',to_jsonb((check_s#>>'{movement,remaining}')::int-cost));check_s:=ml_private.put_player(check_s,a,(check_s->'players'->a)||jsonb_build_object('cell',cell));
  if ml_private.location_stops(check_s->>'version',cell) then check_s:=jsonb_set(check_s,'{movement,remaining}','0');end if;
 end loop;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop
  perform ml_private.need(ml_private.legal_steps(s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');
  origin:=p->>'cell';cost:=ml_private.classic_step_cost(s,a,cell);m:=m||jsonb_build_object('remaining',(m->>'remaining')::int-cost,'path',(m->'path')||to_jsonb(cell));p:=p||jsonb_build_object('cell',cell);s:=ml_private.put_player(s,a,p);s:=ml_private.classic_relocated(s,a,origin,cell);
  if not ml_private.occupied(s,cell,a) then m:=m||jsonb_build_object('lastEmpty',cell);end if;
  if ml_private.location_stops(s->>'version',cell) then m:=jsonb_set(m,'{remaining}','0');end if;
  s:=jsonb_set(s,'{movement}',m);s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell||'，消耗'||cost||'步，余'||(m->>'remaining'));idx:=idx+1;
  if ml_private.classic_owes_water(s,a,origin) then
   s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','walk','path',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(path) with ordinality t(x,n) where n>idx)))||(s->'queue'));
   return ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));
  end if;
 end loop;
 if (m->>'remaining')::int=0 then s:=ml_private.settle_movement(s);s:=s||jsonb_build_object('movement',null,'phase','action');end if;
 return ml_private.resume(s,at);
end $$;
create or replace function ml_private.select_choice(s jsonb,kind text,a integer,at double precision,extra jsonb default '{}') returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare paused boolean:=kind not in ('draw-start','draw-end'); serial integer:=(s->>'choiceSerial')::int+1; begin
 if paused then s:=ml_private.pause(s,at); else s:=ml_private.resume(s,at); end if;
 s:=s||jsonb_build_object('phase','choice','choiceSerial',serial,'choice',jsonb_build_object('id',serial,'kind',kind,'actor',a,'deadline',at+least(case when kind='discard' and s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then 20000 else 10000 end,case when paused then (case when kind='discard' and s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then 20000 else 10000 end) else ml_private.budget(s,at) end),'paused',paused)||extra);
 return ml_private.emit(s,'choice',ml_private.name(s,a)||' 等待选择：'||kind);
end $$;
create or replace function ml_private.settle_movement(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int; m jsonb:=s->'movement'; p jsonb; begin
 if s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') and coalesce((m->>'costDue')::boolean,false) then
  if jsonb_array_length(m->'path')>1 then p:=s->'players'->a; perform ml_private.need((p->>'ap')::int>=1,'移动结算需要1AP'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-1)); s:=ml_private.emit(s,'cost',ml_private.name(s,a)||' 移动结束支付1AP'); end if;
  s:=jsonb_set(s,'{movement,costDue}','false');
 end if; return s;
end $$;
create or replace function ml_private.resolve_attack(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare attack jsonb:=s->'attack'; d jsonb:=ml_private.rule_card(s,attack->>'card'); hits jsonb:='[]'; targets jsonb; p jsonb; a integer:=(attack->>'actor')::int; t integer; actor integer; roll integer:=0; paid integer; amount integer; before_hp jsonb; triggers jsonb; healing integer:=0; begin
 select coalesce(jsonb_agg(x),'[]') into targets from ml_private.arr(attack->'targets') x where not (attack->'cancelled' @> jsonb_build_array(x));
 if jsonb_array_length(targets)>0 and d->>'id' in ('basic-006','basic-009') then s:=ml_private.die(s,d->>'name'); roll:=(s->>'_roll')::int; s:=s-'_roll'; end if;
 for t in select ml_private.n(x)::int from ml_private.arr(targets) x loop p:=s->'players'->t;
  if d ? 'power' then amount:=greatest(0,(d->>'power')::int-(p->>'ap')::int); paid:=least((d->>'power')::int,(p->>'ap')::int); p:=p||jsonb_build_object('ap',(p->>'ap')::int-paid); s:=ml_private.put_player(s,t,p); s:=ml_private.emit(s,'ap',ml_private.name(s,t)||' 被扣'||paid||'AP → '||(p->>'ap')); if amount>0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',amount,'source',a,'category','attack')); end if;
  elsif d->>'id'='basic-008' then
   if (p->>'ap')::int=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',1,'source',a,'category','attack'));
   else paid:=case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then (p->>'ap')::int else least(2,(p->>'ap')::int) end; s:=ml_private.put_player(s,t,p||jsonb_build_object('ap',(p->>'ap')::int-paid)); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('ap',(s->'players'->a->>'ap')::int+paid)); s:=ml_private.emit(s,'ap',case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then ml_private.name(s,a)||' 头锤：从'||ml_private.name(s,t)||'吸收全部'||paid||'AP（目标AP '||paid||'→0）' else ml_private.name(s,a)||' 从'||ml_private.name(s,t)||'吸收'||paid||'AP' end); end if;
  elsif roll>=4 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',1,'source',a,'category','attack')); end if;
 end loop;
 for actor in select ml_private.n(x)::int from ml_private.arr(attack->'elbows') x loop p:=s->'players'->a;
  if (p->>'ap')::int=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',actor,'category','response'));
  else paid:=least(2,(p->>'ap')::int); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-paid)); s:=ml_private.put_player(s,actor,(s->'players'->actor)||jsonb_build_object('ap',(s->'players'->actor->>'ap')::int+paid)); s:=ml_private.emit(s,'ap',ml_private.name(s,actor)||' 肘击反吸'||paid||'AP'); end if;
 end loop;
 before_hp:=s->'players'; s:=ml_private.damage(s,hits); triggers:=s->'_triggers'; s:=s-'_triggers';
 if d->>'id'='basic-006' and (s->'players'->a->>'hp')::int>0 then for t in select ml_private.n(x)::int from ml_private.arr(targets) x loop healing:=healing+(before_hp->t->>'hp')::int-(s->'players'->t->>'hp')::int; end loop; s:=ml_private.heal(s,a,healing); end if;
 if roll>0 and roll<4 then s:=ml_private.emit(s,'miss',(d->>'name')||' 未命中'); end if;
 return s||jsonb_build_object('queue',triggers||jsonb_build_array(jsonb_build_object('kind','cleanup'))||(s->'queue'));
end $$;
create or replace function ml_private.expire(s jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice'; cmd jsonb; cards jsonb; begin
 if c<>'null'::jsonb and at>=(c->>'deadline')::double precision then
  if not (c->>'paused')::boolean and ml_private.budget(s,at)=0 then s:=s||jsonb_build_object('choice',null,'queue','[]'::jsonb,'clock',jsonb_build_object('remaining',0,'since',null)); s:=ml_private.emit(s,'timeout','60秒行动预算用完'); return ml_private.end_turn(s,at,true); end if;
  select coalesce(jsonb_agg(x),'[]') into cards from (select x from ml_private.arr(s->'players'->(c->>'actor')::int->'hand') x order by x limit (c->>'count')::int) q;
  cmd:=jsonb_build_object('id','timeout','revision',s->'revision','actor',c->'actor','type','choose','choice',c->'id','accept',false,'card',null,'cell',null);
  if c->>'kind' in ('discard','water-discard') then cmd:=cmd||jsonb_build_object('cards',cards); end if; return ml_private.choose(s,cmd,at,true);
 end if;
 if c='null'::jsonb and s#>'{clock,since}'<>'null'::jsonb and ml_private.budget(s,at)=0 then s:=ml_private.pause(s,at); s:=ml_private.emit(s,'timeout','60秒行动预算用完'); return ml_private.end_turn(s,at,true); end if;
 return s;
end $$;
create or replace function ml_private.validate(s jsonb) returns void language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb; zones jsonb; a integer; b integer; begin
 perform ml_private.need(s->>'version' in ('web-v0.1.1','web-v0.1.2','web-v0.1.3','web-v0.1.4') and jsonb_array_length(s->'players')=4 and (s->>'round')::int>=1 and (s->>'version'='web-v0.1.4' or (s->>'round')::int<=12),'状态版本/轮次/人数无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb and (select jsonb_agg(member->'character' order by member->'character') from ml_private.arr(s->'players') member)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x),'角色/顺序无效');
 zones:=(s->'deck')||(s->'discard')||(s->'resolving');
 for a in 0..3 loop p:=s->'players'->a; zones:=zones||(p->'hand');
  perform ml_private.need((p->>'hp')::numeric=trunc((p->>'hp')::numeric) and (p->>'hp')::int between 0 and (p->>'maxHp')::int and p->'maxHp'=ml_private.game_data(s,'characters')->(p->>'character')->'hp','生命状态无效');
  perform ml_private.need((p->>'ap')::numeric=trunc((p->>'ap')::numeric) and (p->>'ap')::int>=0 and (p->>'shield')::numeric=trunc((p->>'shield')::numeric) and (p->>'shield')::int between 0 and 2,'AP/护盾无效');
  perform ml_private.need(ml_private.game_data(s,'map') ? (p->>'cell'),'位置无效');
  if (p->>'hp')::int=0 then perform ml_private.need((p->>'ap')::int=0 and (p->>'shield')::int=0 and p->'hand'='[]'::jsonb and p->'eliminated'<>'null'::jsonb,'淘汰清理无效'); end if;
  for b in 0..a-1 loop if (p->>'hp')::int>0 and (s->'players'->b->>'hp')::int>0 and p->'cell'=s->'players'->b->'cell' then perform ml_private.need((s->>'phase'='moving' or s#>>'{choice,kind}'='water-discard') and s->'movement'<>'null'::jsonb,'稳定落点不能重叠'); end if; end loop;
 end loop;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(zones) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'64张实体不守恒或实体重复');
 perform ml_private.need((s#>>'{clock,remaining}')::double precision>=0,'计时预算无效');
end $$;
create or replace function ml_private.create_game(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare rulev text:=coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.4' else 'web-v0.1.1' end); s jsonb; chars jsonb; pair jsonb; teams jsonb; deck jsonb; firstn integer; a integer; c jsonb; id text; players jsonb:='[]'; randomj jsonb; begin
 perform ml_private.runtime_data(rulev,'characterIds');
 perform ml_private.need(jsonb_typeof(setup)='object' and setup->>'mode' in ('ffa','team') and at>=0,'开局输入无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(setup->'seats') x)='[0,1,2,3]'::jsonb,'必须有四个固定座位');
 perform ml_private.need(jsonb_typeof(setup->'seed')='number' and (setup->>'seed')::numeric=trunc((setup->>'seed')::numeric) and (setup->>'seed')::numeric between 0 and 4294967295,'种子必须为uint32');
 randomj:=jsonb_build_object('seed',setup->'seed','dice',coalesce(setup->'dice','[]'),'bombs',coalesce(setup->'bombs','[]'),'reshuffles',coalesce(setup->'reshuffles','[]'),'sortedReshuffles',coalesce(setup->'sortedReshuffles','false'));
 if coalesce((setup->>'secure')::boolean,false) then randomj:=randomj||jsonb_build_object('secure',true); end if;
 s:=jsonb_build_object('version',rulev,'random',randomj);
 if setup ? 'characters' then chars:=setup->'characters'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'characterIds')); chars:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(chars) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x),'四角色必须完整且唯一');
 s:=ml_private.shuffle(s,'[0,1,2,3]'); pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1); s:=s-'_shuffle';
 teams:=setup->'teams'; if teams is null then teams:='[]'; for a in 0..3 loop teams:=teams||to_jsonb(case when pair @> jsonb_build_array(a) then 'A' else 'B' end); end loop; end if;
 if setup->>'mode'='team' then perform ml_private.need(jsonb_array_length(teams)=4 and (select count(*) from ml_private.arr(teams) x where x='"A"')=2 and (select count(*) from ml_private.arr(teams) x where x='"B"')=2,'团战必须2对2'); end if;
 if setup ? 'first' then firstn:=(setup->>'first')::int; else s:=ml_private.int(s,4); firstn:=(s->>'_int')::int; s:=s-'_int'; end if; perform ml_private.need(firstn between 0 and 3,'首位无效');
 if setup ? 'deck' then deck:=setup->'deck'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'allCards')); deck:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(deck) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'牌堆必须64实体完整排列');
 if rulev='web-v0.1.4' then s:=ml_private.allocate_spawns(rulev,chars,s); end if;
 for a in 0..3 loop id:=chars->>a; c:=ml_private.game_data(s,'characters')->id;
  players:=players||jsonb_build_array(jsonb_build_object('seat',a,'character',id,'team',case when setup->>'mode'='team' then teams->>a else 'S'||(a+1) end,'faction',c->'faction','hp',c->'hp','maxHp',c->'hp','ap',5,'shield',0,'cell',case when rulev='web-v0.1.4' then s->'_spawns'->a else c->'spawn' end,'hand','[]'::jsonb,'moved',false,'attacks',0,'skillUsed',false,'rewarded','[]'::jsonb,'kills',0,'damage',0,'eliminated',null));
 end loop;
 s:=s||jsonb_build_object('version',coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.4' else 'web-v0.1.1' end),'revision',0,'time',at,'mode',setup->'mode','players',players,'order',(select jsonb_agg((firstn+i)%4) from generate_series(0,3) i),'cursor',0,'active',firstn,'round',1,'phase','resolving','deck',deck,'discard','[]'::jsonb,'resolving','[]'::jsonb,'queue','[]'::jsonb,'choice',null,'choiceSerial',0,'attack',null,'movement',null,'safe',ml_private.safe_for_version(s->>'version',1),'bomb',null,'forecast',null,'clock',jsonb_build_object('remaining',60000,'since',null),'events','[]'::jsonb,'eventSerial',0,'batch',0,'reshuffleCount',0,'seen','[]'::jsonb,'result',null);
 s:=s-'_spawns'; if rulev='web-v0.1.4' then s:=s||jsonb_build_object('classic',jsonb_build_object('poison','[]'::jsonb,'bombs','[]'::jsonb,'exposure',(select jsonb_agg(jsonb_build_object('region',null,'streak',0)) from generate_series(0,3)),'shipUsed','[]'::jsonb,'farmClosed',false)); end if;
 s:=ml_private.emit(s,'setup','四人'||case when setup->>'mode'='ffa' then '各自为战' else '2对2' end||' · '||(s->>'version')); for a in 0..3 loop s:=ml_private.draw(s,a,4); end loop;
 s:=ml_private.start_round(s,at); perform ml_private.validate(s); return s;
end $$;
create or replace function ml_private.escape(s jsonb,a integer,cell text,left_steps integer) returns boolean language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare c jsonb; cost integer; begin
 if not ml_private.classic_enter(s,cell) then return false;end if;
 if ml_private.location_stops(s->>'version',cell) and ml_private.occupied(s,cell,a) then return false; end if;
 if not ml_private.occupied(s,cell,a) then return true; end if;
 for c in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop
  cost:=case when c->>'terrain'='water' then 2 else 1 end;
  if cost<=left_steps and ml_private.distance_for_version(s->>'version',cell,c->>'id')=1 and ml_private.escape(s,a,c->>'id',left_steps-cost) then return true; end if;
 end loop; return false;
end $$;
create or replace function ml_private.end_turn(s jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int; begin
 if s->'movement'<>'null'::jsonb then s:=ml_private.settle_movement(s);s:=ml_private.classic_relocated(s,a,s->'players'->a->>'cell',s#>>'{movement,lastEmpty}'); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('cell',s#>'{movement,lastEmpty}')); s:=jsonb_set(s,'{movement}','null'); s:=ml_private.emit(s,'move','移动结束，落点'||(s->'players'->a->>'cell')||'，剩余额度作废'); end if;
 s:=s||jsonb_build_object('phase','resolving','queue',(s->'queue')||jsonb_build_array(jsonb_build_object('kind',case when timeout then 'discard' else 'end-draw' end))); return ml_private.pump(s,at);
end $$;
create or replace function ml_private.teleport_cells(s jsonb,a integer) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where c->>'terrain'='land' and ml_private.classic_enter(s,c->>'id') and ml_private.distance_for_version(s->>'version',s->'players'->a->>'cell',c->>'id')<=3 and not ml_private.occupied(s,c->>'id') $$;
create or replace function ml_private.legal_steps_legacy(s jsonb) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select case when s->>'phase'<>'moving' or s->'movement'='null'::jsonb then '[]'::jsonb else
 (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where ml_private.distance_for_version(s->>'version',s->'players'->(s->>'active')::int->>'cell',c->>'id')=1 and ml_private.escape(s,(s->>'active')::int,c->>'id',(s#>>'{movement,remaining}')::int-case when c->>'terrain'='water' then 2 else 1 end) and (s#>>'{movement,remaining}')::int>=case when c->>'terrain'='water' then 2 else 1 end) end $$;
create or replace function ml_private.legal_steps(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version'<>'web-v0.1.4' then return ml_private.legal_steps_legacy(s);end if;
 if s->>'phase'<>'moving' or s->'movement'='null'::jsonb then return '[]';end if;
 return (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where ml_private.classic_step_cost(s,(s->>'active')::int,c->>'id')<=(s#>>'{movement,remaining}')::int and ml_private.escape(s,(s->>'active')::int,c->>'id',(s#>>'{movement,remaining}')::int-ml_private.classic_step_cost(s,(s->>'active')::int,c->>'id')));
end $$;
create or replace function ml_private.pump(s jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare task jsonb; a integer; p jsonb; countn integer; cards jsonb; kind text; cells jsonb; cursor integer; guard integer:=0; begin
 while s->'choice'='null'::jsonb and s->>'phase'<>'over' and jsonb_array_length(s->'queue')>0 loop
  guard:=guard+1; perform ml_private.need(guard<200,'内部流程未收敛'); task:=s->'queue'->0; s:=jsonb_set(s,'{queue}',(s->'queue')-0); a:=coalesce((task->>'actor')::int,(s->>'active')::int); p:=s->'players'->a;
  case task->>'kind'
   when 'water' then if ml_private.classic_owes_water(s,a) then s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;
   when 'classic-start' then
    for a in 0..3 loop p:=s->'players'->a;if (p->>'hp')::int>0 then p:=p||jsonb_build_object('skillUsed',false,'rewarded','[]'::jsonb);if (p->>'ap')::int<5 then p:=p||jsonb_build_object('ap',(p->>'ap')::int+3);s:=ml_private.put_player(s,a,p);s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 轮开始获得3AP → '||(p->>'ap'));end if;s:=ml_private.put_player(s,a,p);end if;end loop;
    s:=ml_private.classic_refresh(s);s:=ml_private.emit(s,'round','第'||(s->>'round')||'轮开始，毒区：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,poison}') x)||case when (s#>>'{classic,farmClosed}')::boolean then '；高唐农场已封闭' else '' end);s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','after-env'))||(s->'queue'));
   when 'round-next' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=s||jsonb_build_object('round',(s->>'round')::int+1,'cursor',0);s:=ml_private.start_round(s,at);end if;
   when 'walk' then s:=ml_private.classic_walk(s,coalesce(task->'path','[]'),at);
   when 'after-env' then s:=ml_private.finish(s,false,at); if s->>'phase'<>'over' then cursor:=0; while (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1; end loop; s:=s||jsonb_build_object('cursor',cursor,'queue',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue')); end if;
   when 'turn-start' then
    if s->>'version'='web-v0.1.4' then s:=jsonb_set(s,'{classic,shipUsed}',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(s#>'{classic,shipUsed}') x where x<>to_jsonb(a)));end if;
    s:=s||jsonb_build_object('active',a,'phase','resolving','clock',jsonb_build_object('remaining',60000,'since',at)); p:=p||jsonb_build_object('moved',false,'attacks',0); s:=ml_private.put_player(s,a,p);
    if p->>'character'='character-031' and (p->>'ap')::int<6 then p:=p||jsonb_build_object('ap',6); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 行动开始补至6AP'); end if;
    if ml_private.location_personal_ap(s->>'version',p,(s->>'round')::int)>(p->>'ap')::int then p:=p||jsonb_build_object('ap',ml_private.location_personal_ap(s->>'version',p,(s->>'round')::int)); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 尚德荟获得1AP → '||(p->>'ap')); end if;
    s:=ml_private.emit(s,'turn',ml_private.name(s,a)||' 开始行动'); if (s->>'round')::int>1 then s:=ml_private.draw(s,a,ml_private.location_draw_count(s->>'version',p->>'cell',(s->>'round')::int)); end if;
    s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','action'))||(s->'queue')); if p->>'character'='character-027' then s:=ml_private.select_choice(s,'draw-start',a,at); end if;
   when 'action' then s:=jsonb_set(s,'{phase}','"action"'); s:=ml_private.resume(s,at);
   when 'end-draw' then s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','discard'))||(s->'queue')); if p->>'character'='character-027' and (p->>'hp')::int>0 and ml_private.budget(s,at)>0 then s:=ml_private.select_choice(s,'draw-end',a,at); end if;
   when 'discard' then countn:=jsonb_array_length(p->'hand')-greatest(0,floor((p->>'hp')::numeric)::int); s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','next'))||(s->'queue')); if (p->>'hp')::int>0 and countn>0 then s:=ml_private.select_choice(s,'discard',a,at,jsonb_build_object('count',countn,'cards',p->'hand')); end if;
   when 'next' then s:=ml_private.next_turn(s,at);
   when 'response' then if not (s#>'{attack,cancelled}' @> jsonb_build_array(a)) and s->'attack'<>'null'::jsonb and (p->>'hp')::int>0 then
    select coalesce(jsonb_agg(c),'[]') into cards from ml_private.arr(p->'hand') c where (ml_private.rule_card(s,c#>>'{}')->>'id'='basic-001' or (ml_private.rule_card(s,c#>>'{}')->>'id'='basic-002' and ml_private.rule_card(s,s#>>'{attack,card}')->>'id'='basic-008')) and (p->>'ap')::int>=(ml_private.rule_card(s,c#>>'{}')->>'cost')::int;
    if jsonb_array_length(cards)>0 then s:=ml_private.select_choice(s,'response',a,at,jsonb_build_object('cards',cards)); end if; end if;
   when 'resolve' then s:=ml_private.resolve_attack(s);
   when 'cleanup' then s:=s||jsonb_build_object('discard',(s->'discard')||(s->'resolving'),'resolving','[]'::jsonb,'attack',null); s:=ml_private.finish(s,false,at);
    if s->>'phase'<>'over' then if (s->'players'->(s->>'active')::int->>'hp')::int>0 then s:=jsonb_set(s,'{phase}','"action"'); s:=ml_private.resume(s,at); else s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','next'))||(s->'queue')); end if; end if;
   when 'trigger' then
    if (p->>'hp')::int<=0 then continue; end if; kind:=task->>'trigger';
    if kind='lemon-reward' then if task ? 'source' and not (s->'players'->(task->>'source')::int->'rewarded' @> jsonb_build_array(a)) then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('source',task->'source')); end if;
    elsif not (p->>'skillUsed')::boolean then
     if (kind='lemon-support' and (p->>'ap')::int>=1) or (kind='runner-roll' and (p->>'ap')::int>=2) then s:=ml_private.select_choice(s,kind,a,at); end if;
     if kind='teleport' then cells:=ml_private.teleport_cells(s,a); if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('cells',cells)); end if; end if;
    end if;
   else raise exception '未知内部任务';
  end case;
 end loop; return s;
end $$;
create or replace function ml_private.choose(s jsonb,cmd jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice'; a integer:=(c->>'actor')::int; p jsonb:=s->'players'->a; kind text:=c->>'kind'; card text:=cmd->>'card'; cell text:=cmd->>'cell'; cards jsonb; actor integer; paid integer; begin
 perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期'); perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');
 case kind
  when 'draw-start','draw-end' then if coalesce((cmd->>'accept')::boolean,false) then s:=ml_private.draw(s,a,1); end if;
  when 'response' then if card is not null and card<>'' then perform ml_private.need(c->'cards' ? card,'此牌不能响应'); paid:=(ml_private.rule_card(s,card)->>'cost')::int; p:=p||jsonb_build_object('ap',(p->>'ap')::int-paid,'hand',(p->'hand')-card); s:=ml_private.put_player(s,a,p); s:=s||jsonb_build_object('resolving',(s->'resolving')||to_jsonb(card)); s:=jsonb_set(s,'{attack,cancelled}',(s#>'{attack,cancelled}')||to_jsonb(a)); if ml_private.rule_card(s,card)->>'id'='basic-002' then s:=jsonb_set(s,'{attack,elbows}',(s#>'{attack,elbows}')||to_jsonb(a)); end if; s:=ml_private.emit(s,'response',ml_private.name(s,a)||' 使用'||(ml_private.rule_card(s,card)->>'name')||'，支付'||paid||'AP'); else s:=ml_private.emit(s,'response',ml_private.name(s,a)||' 放弃响应'); end if;
  when 'lemon-reward' then if coalesce((cmd->>'accept')::boolean,false) then actor:=(c->>'source')::int; s:=ml_private.put_player(s,actor,(s->'players'->actor)||jsonb_build_object('rewarded',(s->'players'->actor->'rewarded')||to_jsonb(a))); s:=ml_private.draw(s,a,1); end if;
  when 'lemon-support' then if coalesce((cmd->>'accept')::boolean,false) then perform ml_private.need((p->>'ap')::int>=1 and not (p->>'skillUsed')::boolean,'支援不可用'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-1,'skillUsed',true)); for actor in 0..3 loop if (s->'players'->actor->>'hp')::int>0 and (actor=a or (s->>'mode'='team' and s->'players'->actor->>'team'=p->>'team')) then s:=ml_private.draw(s,actor,1); end if; end loop; s:=ml_private.emit(s,'skill',ml_private.name(s,a)||' 支援，支付1AP'); end if;
  when 'runner-roll' then if coalesce((cmd->>'accept')::boolean,false) then perform ml_private.need((p->>'ap')::int>=2 and not (p->>'skillUsed')::boolean,'恢复判定不可用'); s:=ml_private.put_player(s,a,p||jsonb_build_object('skillUsed',true)); s:=ml_private.die(s,'跑者恢复'); paid:=(s->>'_roll')::int; s:=s-'_roll'; if paid>=4 then s:=jsonb_set(s,'{choice}','null'); return ml_private.select_choice(s,'runner-pay',a,at); end if; end if;
  when 'runner-pay' then if coalesce((cmd->>'accept')::boolean,false) then perform ml_private.need((p->>'ap')::int>=2,'恢复费用不足'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-2)); s:=ml_private.heal(s,a,1); s:=ml_private.emit(s,'skill',ml_private.name(s,a)||' 恢复支付2AP'); end if;
  when 'teleport' then if cell is not null and cell<>'' then perform ml_private.need(c->'cells' ? cell and ml_private.teleport_cells(s,a) ? cell,'传送须为距离≤3的空陆地'); s:=ml_private.put_player(s,a,p||jsonb_build_object('cell',cell,'skillUsed',true));s:=ml_private.classic_relocated(s,a,p->>'cell',cell); s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' 传送至'||cell||case when s->'safe' ? cell then '' else '（毒圈外）' end); end if;
  when 'discard','water-discard' then cards:=coalesce(cmd->'cards','[]'); perform ml_private.need(jsonb_array_length(cards)=(c->>'count')::int and (select count(distinct x) from ml_private.arr(cards) x)=jsonb_array_length(cards) and p->'hand' @> cards,'请选择准确数量的不同手牌弃置'); select coalesce(jsonb_agg(x),'[]') into p from ml_private.arr(p->'hand') x where not (cards @> jsonb_build_array(x)); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('hand',p)); s:=s||jsonb_build_object('discard',(s->'discard')||cards); s:=ml_private.emit(s,case when timeout then 'timeout-discard' else 'discard' end,ml_private.name(s,a)||case when timeout then ' 超时代弃' else ' 自选弃牌' end||jsonb_array_length(cards)||'张',cards);
  else raise exception '未知选择';
 end case;
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||kind); end if;
 s:=s||jsonb_build_object('choice',null,'phase','resolving'); return ml_private.pump(s,at);
end $$;
create or replace function ml_private.dispatch(previous jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare s jsonb:=previous; a integer; p jsonb; d jsonb; c jsonb; m jsonb; v jsonb; typ text:=cmd->>'type'; card text:=cmd->>'card'; cells jsonb; cell text; cost integer; left_steps integer; deadline double precision; guard integer:=0; changed boolean:=false; targets jsonb; txt text; begin
 perform ml_private.need(jsonb_typeof(cmd)='object','命令必须为对象');
 perform ml_private.need(jsonb_typeof(cmd->'actor')='number' and (cmd->>'actor')::numeric=trunc((cmd->>'actor')::numeric) and (cmd->>'actor')::int between 0 and 3 and jsonb_typeof(cmd->'revision')='number' and (cmd->>'revision')::numeric=trunc((cmd->>'revision')::numeric) and (cmd->>'revision')::bigint>=0,'座位/命令版本必须为有效整数');
 perform ml_private.need(typ in ('play','move','step','stop','end','choose','tick','location'),'未知命令');
 if typ='play' then perform ml_private.need(jsonb_typeof(cmd->'card')='string' and jsonb_typeof(cmd->'targets')='array','出牌/目标输入无效'); for v in select * from ml_private.arr(cmd->'targets') loop perform ml_private.need(jsonb_typeof(v)='number' and (v#>>'{}')::numeric=trunc((v#>>'{}')::numeric) and ml_private.n(v) between 0 and 3,'目标输入无效'); end loop; end if;
 if typ='location' then perform ml_private.need(cmd->>'kind' in ('ship','commute') and jsonb_typeof(cmd->'cell')='string','地点动作输入无效');end if;
 if typ='step' then perform ml_private.need(jsonb_typeof(cmd->'path')='array','路径必须为数组'); for v in select * from ml_private.arr(cmd->'path') loop perform ml_private.need(jsonb_typeof(v)='string','路径格无效'); end loop; end if;
 if typ='choose' then
  perform ml_private.need(jsonb_typeof(cmd->'choice')='number' and (cmd->>'choice')::numeric=trunc((cmd->>'choice')::numeric) and (cmd->>'choice')::bigint>0,'选择编号无效');
  if cmd ? 'accept' then perform ml_private.need(jsonb_typeof(cmd->'accept')='boolean','发动选项必须为布尔值'); end if;
  if cmd ? 'card' then perform ml_private.need(jsonb_typeof(cmd->'card') in ('string','null'),'响应牌输入无效'); end if;
  if cmd ? 'cell' then perform ml_private.need(jsonb_typeof(cmd->'cell') in ('string','null'),'传送格输入无效'); end if;
  if cmd ? 'cards' then perform ml_private.need(jsonb_typeof(cmd->'cards')='array','弃牌必须为数组'); for v in select * from ml_private.arr(cmd->'cards') loop perform ml_private.need(jsonb_typeof(v)='string','弃牌输入无效'); end loop; end if;
 end if;
 perform ml_private.need(at>=(s->>'time')::double precision,'时钟必须单调'); perform ml_private.need(cmd->'revision'=s->'revision','命令版本过期'); perform ml_private.need(jsonb_typeof(cmd->'id')='string' and length(cmd->>'id')>0 and not (s->'seen' ? (cmd->>'id')),'重复命令'); perform ml_private.need(s->>'phase'<>'over','对局已经结束');
 a:=(cmd->>'actor')::int;
 if typ='tick' then
  while s->>'phase'<>'over' loop deadline:=coalesce((s#>>'{choice,deadline}')::double precision,(s#>>'{clock,since}')::double precision+(s#>>'{clock,remaining}')::double precision); exit when deadline is null or deadline>at;
   exit when s->>'version'='web-v0.1.4' and guard>=999;guard:=guard+1; perform ml_private.need(guard<1000,'超时流程未收敛'); s:=ml_private.expire(s,deadline); changed:=true;
  end loop;
  if not changed then return jsonb_build_object('state',previous,'ok',true); end if;
 else
  perform ml_private.need(not (case when s->'choice'<>'null'::jsonb then at>=(s#>>'{choice,deadline}')::double precision else s#>'{clock,since}'<>'null'::jsonb and ml_private.budget(s,at)=0 end),'命令已超时');
  if typ='choose' then perform ml_private.need(s->'choice'<>'null'::jsonb,'当前没有选择窗口'); s:=ml_private.choose(s,cmd,at);
  else
   p:=s->'players'->a; perform ml_private.need(a=(s->>'active')::int and (p->>'hp')::int>0,'只有当前存活行动者可操作'); perform ml_private.need(s->'choice'='null'::jsonb,'请先完成当前选择');
   case typ
    when 'step' then if s->>'version'='web-v0.1.4' then perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb and jsonb_array_length(cmd->'path')>0,'尚未开始移动或路径为空');s:=ml_private.classic_walk(s,cmd->'path',at);else 
     perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb,'尚未开始移动'); perform ml_private.need(jsonb_array_length(cmd->'path')>0,'移动路径不能为空'); m:=s->'movement';
     for cell in select x#>>'{}' from ml_private.arr(cmd->'path') x loop
      perform ml_private.need(ml_private.game_data(s,'map') ? cell and ml_private.distance_for_version(s->>'version',p->>'cell',cell)=1,'只能正交移动到棋盘内相邻格'); cost:=case when ml_private.game_data(s,'map')->cell->>'terrain'='water' then 2 else 1 end; left_steps:=(m->>'remaining')::int-cost;
      perform ml_private.need(left_steps>=0,'移动步数不足'); perform ml_private.need(ml_private.escape(s,a,cell,left_steps),'此路径会困在占用格');
      p:=p||jsonb_build_object('cell',cell); m:=m||jsonb_build_object('remaining',left_steps,'path',(m->'path')||to_jsonb(cell)); if not ml_private.occupied(s,cell,a) then m:=m||jsonb_build_object('lastEmpty',cell); end if;
      s:=ml_private.put_player(s,a,p); if ml_private.location_stops(s->>'version',cell) then left_steps:=0; m:=jsonb_set(m,'{remaining}','0'); end if;
      s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell||'，消耗'||cost||'步，余'||left_steps);
     end loop;
     s:=jsonb_set(s,'{movement}',m); if (m->>'remaining')::int=0 then s:=ml_private.settle_movement(s); s:=s||jsonb_build_object('movement',null,'phase','action'); end if;
    end if;
    when 'stop' then perform ml_private.need(s->'movement'<>'null'::jsonb,'尚未开始移动'); perform ml_private.need(not ml_private.occupied(s,p->>'cell',a),'不能停在占用格'); s:=ml_private.settle_movement(s); s:=s||jsonb_build_object('movement',null,'phase','action'); s:=ml_private.emit(s,'move','主动结束移动，未用额度作废');
    when 'end' then perform ml_private.need(s->'movement'='null'::jsonb or not ml_private.occupied(s,p->>'cell',a),'不能在占用格结束行动'); s:=ml_private.end_turn(s,at);
    else
     perform ml_private.need(s->>'phase'='action','请先完成移动');
     if typ='location' then
      v:=s||jsonb_build_object('shipUsed',coalesce(s#>'{classic,shipUsed}','[]'),'farmClosed',coalesce(s#>'{classic,farmClosed}','false'));cell:=cmd->>'cell';
      perform ml_private.need(ml_private.location_destinations(v,a,cmd->>'kind') ? cell,'地点传送当前不可用或落点不合法');
      if cmd->>'kind'='ship' then s:=jsonb_set(s,'{classic,shipUsed}',(s#>'{classic,shipUsed}')||to_jsonb(a));else s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',0));end if;
      s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('cell',cell));s:=ml_private.classic_relocated(s,a,p->>'cell',cell);
      s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' '||case when cmd->>'kind'='ship' then '飞船' else '通校' end||'至'||cell);
      if ml_private.classic_owes_water(s,a,p->>'cell') then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(jsonb_build_object('kind','action')));s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;
     elsif typ='move' then perform ml_private.need(not (p->>'moved')::boolean,'本个人回合已使用基础移动'); perform ml_private.need((p->>'ap')::int>=ml_private.location_basic_cost(s->>'version',p->>'cell'),'移动需要1AP'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-case when s->>'version'='web-v0.1.1' then 1 else 0 end,'moved',true)); s:=ml_private.die(s,'基础移动'); left_steps:=ceil((s->>'_roll')::numeric/2)::int; s:=s-'_roll'; s:=s||jsonb_build_object('movement',jsonb_build_object('remaining',left_steps,'lastEmpty',p->'cell','origin',p->'cell','path',jsonb_build_array(p->'cell'))||case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then jsonb_build_object('costDue',ml_private.location_basic_cost(s->>'version',p->>'cell')>0) else '{}'::jsonb end,'phase','moving'); s:=ml_private.emit(s,'cost',ml_private.name(s,a)||case when ml_private.location_basic_cost(s->>'version',p->>'cell')=0 then ' 操场免费移动，获得' when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then ' 移动结束扣费，获得' else ' 移动支付1AP，获得' end||left_steps||'步');
     elsif typ='play' then
      d:=ml_private.rule_card(s,card); perform ml_private.need(ml_private.location_card_allowed(s->>'version',p->>'cell',card),'当前位置禁止使用此牌'); targets:=cmd->'targets'; perform ml_private.need(p->'hand' ? card,'手中没有该实体牌'); perform ml_private.need(d is not null and d->>'type'<>'response','响应牌只能在对应窗口使用'); cost:=(d->>'cost')::int; perform ml_private.need((p->>'ap')::int>=cost,'行动点不足');
      if d->>'type'='attack' then perform ml_private.need(s->>'version' in ('web-v0.1.3','web-v0.1.4') or (p->>'attacks')::int<2,'本回合最多两张攻击'); perform ml_private.need(jsonb_array_length(targets) between 1 and case when coalesce((d->>'group')::boolean,false) then case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then 3 else 2 end else 1 end and (select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标数量无效'); perform ml_private.need(ml_private.targets(s,a,card) @> targets,'目标不合法：检查范围、队伍、lemon嘲讽或群体免疫');
      else perform ml_private.need(targets='[]'::jsonb,'补给只能对自己'); end if;
      if s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4') then s:=jsonb_set(s,'{clock}',jsonb_build_object('remaining',60000,'since',at)); end if;
      p:=p||jsonb_build_object('ap',(p->>'ap')::int-cost,'hand',(p->'hand')-card); s:=ml_private.put_player(s,a,p); s:=jsonb_set(s,'{resolving}',(s->'resolving')||to_jsonb(card)); txt:=ml_private.name(s,a)||' 使用'||(d->>'name')||'，支付'||cost||'AP'; if d->>'type'='attack' then txt:=txt||'，目标'||(select string_agg(ml_private.name(s,ml_private.n(x)::int),'、') from ml_private.arr(targets) x); end if; s:=ml_private.emit(s,'play',txt,jsonb_build_object('actor',a,'card',card,'targets',targets));
      if d->>'type'='attack' then
       s:=ml_private.put_player(s,a,p||jsonb_build_object('attacks',(p->>'attacks')::int+1));
       select coalesce(jsonb_agg(jsonb_build_object('kind','response','actor',x)),'[]') into cells from ml_private.arr(s->'order') x where targets @> jsonb_build_array(x);
       s:=s||jsonb_build_object('attack',jsonb_build_object('actor',a,'card',card,'targets',targets,'cancelled',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(targets) x where not ml_private.location_effect_allowed(s->>'version',s->'players'->(x#>>'{}')::int->>'cell',card)),'elbows','[]'::jsonb),'phase','resolving','queue',(s->'queue')||cells||jsonb_build_array(jsonb_build_object('kind','resolve'))); s:=ml_private.pump(s,at);
      else s:=ml_private.heal(s,a,case when d->>'id'='basic-046' then 2 else 1 end,true);
       if d->>'id'='basic-045' then p:=s->'players'->a; cost:=least(1,2-(p->>'shield')::int); p:=p||jsonb_build_object('shield',(p->>'shield')::int+cost); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'shield',ml_private.name(s,a)||' 获得'||cost||'护盾 → '||(p->>'shield')); end if;
       if d->>'id'='basic-047' then s:=ml_private.draw(s,a,2); end if; s:=s||jsonb_build_object('discard',(s->'discard')||(s->'resolving'),'resolving','[]'::jsonb); s:=ml_private.finish(s,false,at);
      end if;
     else raise exception '未知命令'; end if;
   end case;
  end if;
 end if;
 s:=s||jsonb_build_object('seen',(s->'seen')||to_jsonb(cmd->>'id'),'revision',(s->>'revision')::bigint+1,'time',at); perform ml_private.validate(s); return jsonb_build_object('state',s,'ok',true);
exception when others then return jsonb_build_object('state',previous,'ok',false,'error',sqlerrm);
end $$;
create or replace function ml_private.public_view(s jsonb,viewer integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare result jsonb; players jsonb:='[]'; p jsonb; c jsonb:=s->'choice'; events jsonb; legal jsonb:='{}'; card text; begin
 perform ml_private.need(viewer between 0 and 3,'无效视图身份');
 for p in select * from ml_private.arr(s->'players') loop players:=players||jsonb_build_array((p-'hand')||jsonb_build_object('handCount',jsonb_array_length(p->'hand'))||case when (p->>'seat')::int=viewer then jsonb_build_object('hand',p->'hand') else '{}'::jsonb end); end loop;
 if c<>'null'::jsonb then c:=jsonb_strip_nulls(jsonb_build_object('id',c->'id','kind',c->'kind','actor',c->'actor','deadline',c->'deadline','source',c->'source'))||case when (c->>'actor')::int=viewer then (s->'choice')-'paused'-'id'-'kind'-'actor'-'deadline'-'source' else '{}'::jsonb end; end if;
 select coalesce(jsonb_agg((e-'data')||case when e->>'type'='dice' then jsonb_build_object('roll',e->'data') else '{}'::jsonb end),'[]') into events from ml_private.arr(s->'events') e;
 result:=s-'players'-'deck'-'random'-'queue'-'seen'-'time'-'cursor'-'choiceSerial'-'eventSerial'-'batch'-'reshuffleCount';
 result:=result||jsonb_build_object('players',players,'deckCount',jsonb_array_length(s->'deck'),'choice',c,'events',events);
 for card in select x#>>'{}' from ml_private.arr(s->'players'->viewer->'hand') x loop legal:=legal||jsonb_build_object(card,ml_private.targets(s,viewer,card)); end loop;
 return result||jsonb_build_object('actions',jsonb_build_object('targets',legal,'steps',case when viewer=(s->>'active')::int then ml_private.legal_steps(s) else '[]'::jsonb end));
end $$;
create or replace function ml_private.damage(s jsonb,hits jsonb,environment boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare h jsonb; p jsonb; a integer; src integer; blocked integer; loss integer; injured jsonb:='[]'; triggers jsonb:='[]'; begin
 s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));
 for h in select * from ml_private.arr(hits) loop
  a:=(h->>'target')::int; p:=s->'players'->a; if (p->>'hp')::int<=0 or (h->>'amount')::int<=0 then continue; end if;
  blocked:=case when environment and s->>'version'<>'web-v0.1.4' then 0 else least((p->>'shield')::int,(h->>'amount')::int) end; loss:=least((p->>'hp')::int,(h->>'amount')::int-blocked);
  p:=p||jsonb_build_object('shield',(p->>'shield')::int-blocked,'hp',(p->>'hp')::int-loss); s:=ml_private.put_player(s,a,p); src:=(h->>'source')::int;
  if src is not null and ml_private.enemy(s,src,a) then s:=ml_private.put_player(s,src,(s->'players'->src)||jsonb_build_object('damage',(s->'players'->src->>'damage')::int+loss,'kills',(s->'players'->src->>'kills')::int+case when (p->>'hp')::int=0 and loss>0 then 1 else 0 end)); end if;
  s:=ml_private.emit(s,'damage',ml_private.name(s,a)||' '||case when environment then '环境' else '普通' end||'伤害'||(h->>'amount')||'，护盾抵挡'||blocked||'，实际失血'||loss,h||jsonb_build_object('blocked',blocked,'loss',loss,'batch',s->'batch'));
  if loss>0 then injured:=injured||jsonb_build_array(h||jsonb_build_object('loss',loss)); end if;
 end loop;
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int=0 and p->'eliminated'='null'::jsonb then
  s:=s||jsonb_build_object('discard',(s->'discard')||(p->'hand')); p:=p||jsonb_build_object('eliminated',s->'batch','ap',0,'shield',0,'hand','[]'::jsonb); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'eliminate',ml_private.name(s,a)||' 淘汰（批次'||(s->>'batch')||'）'); end if; end loop;
 for a in select ml_private.n(x)::int from ml_private.arr(s->'order') x loop
  p:=s->'players'->a; select x into h from ml_private.arr(injured) x where (x->>'target')::int=a limit 1;
  if h is null or (p->>'hp')::int<=0 then continue; end if; src:=(h->>'source')::int;
  if p->>'character'='character-004' then
   if src is not null and h->>'category'='attack' and ml_private.enemy(s,src,a) and (s->'players'->src->>'hp')::int>0 and not (p->'rewarded' @> jsonb_build_array(src)) then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',src,'trigger','lemon-reward','source',a)); end if;
   triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','lemon-support'));
  elsif p->>'character'='character-031' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','runner-roll'));
  elsif p->>'character'='character-037' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','teleport')); end if;
 end loop; return s||jsonb_build_object('_triggers',triggers);
end $$;
create or replace function ml_private.start_round_legacy(s jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer; p jsonb; hits jsonb:='[]'; amount integer; r integer:=(s->>'round')::int; bomb jsonb:='null'; begin
 if (s#>>'{forecast,round}')::int=r then bomb:=s#>'{forecast,bomb}'; end if;
 s:=s||jsonb_build_object('safe',ml_private.safe_for_version(s->>'version',r),'bomb',bomb,'forecast',null);
 s:=ml_private.emit(s,'round','第'||r||'轮开始，安全格'||jsonb_array_length(s->'safe')||'，轰炸：'||coalesce(bomb#>>'{}','无'));
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int>0 then p:=p||jsonb_build_object('skillUsed',false,'rewarded','[]'::jsonb);
  if (p->>'ap')::int<5 then p:=p||jsonb_build_object('ap',(p->>'ap')::int+3); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 轮开始获得3AP → '||(p->>'ap')); end if; s:=ml_private.put_player(s,a,p);
  amount:=case when s->'safe' ? (p->>'cell') then 0 when r<=3 then 0 when r<=7 then 1 else 2 end+case when ml_private.game_data(s,'map')->(p->>'cell')->'region'=bomb then 1 else 0 end;
  hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',amount,'source',null,'category','environment'));
 end if; end loop;
 s:=ml_private.pause(s,at); s:=jsonb_set(s,'{phase}','"resolving"'); s:=ml_private.damage(s,hits,true);
 s:=s||jsonb_build_object('queue',(s->'queue')||(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','after-env'))); s:=s-'_triggers'; return ml_private.pump(s,at);
end $$;
create or replace function ml_private.start_round(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version'<>'web-v0.1.4' then return ml_private.start_round_legacy(s,at);end if;
 s:=ml_private.pause(s,at);s:=jsonb_set(s,'{phase}','"resolving"');
 s:=jsonb_set(s,'{queue}',(s->'queue')||(select jsonb_agg(jsonb_build_object('kind','water','actor',x)) from ml_private.arr(s->'order') x)||jsonb_build_array(jsonb_build_object('kind','classic-start')));return ml_private.pump(s,at);
end $$;
create or replace function ml_private.next_turn_legacy(s jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare active integer:=(s->>'active')::int; cursor integer:=(s->>'cursor')::int+1; r integer:=(s->>'round')::int; candidates jsonb; bomb jsonb:='null'; begin
 s:=ml_private.pause(s,at); s:=ml_private.put_player(s,active,(s->'players'->active)||jsonb_build_object('moved',false,'attacks',0));
 while cursor<4 and (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1; end loop;
 s:=jsonb_set(s,'{cursor}',to_jsonb(cursor));
 if cursor<4 then return s||jsonb_build_object('queue',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue')); end if;
 if r=12 then return ml_private.finish(s,true,at); end if;
 if r>=2 then candidates:=ml_private.candidates_for_version(s->>'version',r+1);
  if jsonb_array_length(s#>'{random,bombs}')>0 then bomb:=s#>'{random,bombs,0}'; s:=jsonb_set(s,'{random,bombs}',(s#>'{random,bombs}')-0);
  else s:=ml_private.int(s,jsonb_array_length(candidates)); bomb:=candidates->(s->>'_int')::int; s:=s-'_int'; end if;
  perform ml_private.need(candidates @> jsonb_build_array(bomb),'轰炸区域无效');
 end if;
 s:=s||jsonb_build_object('forecast',jsonb_build_object('round',r+1,'safe',ml_private.safe_for_version(s->>'version',r+1),'bomb',bomb));
 s:=ml_private.emit(s,'forecast','预告第'||(r+1)||'轮：安全格'||jsonb_array_length(ml_private.safe_for_version(s->>'version',r+1))||'，轰炸'||coalesce(bomb#>>'{}','无'),s->'forecast');
 s:=s||jsonb_build_object('round',r+1,'cursor',0); return ml_private.start_round(s,at);
end $$;
create or replace function ml_private.next_turn(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version'<>'web-v0.1.4' then return ml_private.next_turn_legacy(s,at);end if;
 s:=ml_private.pause(s,at);a:=(s->>'active')::int;s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('moved',false,'attacks',0));cursor:=(s->>'cursor')::int+1;
 while cursor<4 and (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1;end loop;s:=jsonb_set(s,'{cursor}',to_jsonb(cursor));
 if cursor<4 then return jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue'));end if;
 s:=jsonb_set(s,'{phase}','"resolving"');s:=ml_private.classic_environment(s);s:=ml_private.emit(s,'environment','第'||(s->>'round')||'轮末，轰炸：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,bombs}') x));s:=ml_private.damage(s,s->'_hits',true);s:=s-'_hits';
 s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','round-next')));return s-'_triggers';
end $$;
create or replace function ml_private.safe_for_version(v text,r integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$
 select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.runtime_data(v,'cells')) c where v='web-v0.1.4' or r<=3 or (r<=5 and (c->>'col')::int between 2 and 7) or (r>5 and r<=7 and (c->>'col')::int between 3 and 6) or (r>7 and r<=9 and (c->>'row')::int between 2 and 3 and (c->>'col')::int between 3 and 6) or (r>9 and (c->>'row')::int between 2 and 3 and (c->>'col')::int between 3 and 5) $$;
create or replace function ml_private.room_v1(p_request jsonb) returns jsonb
language plpgsql security definer set search_path=pg_catalog,ml_private as $$
declare at bigint:=ml_private.now_ms(); op text:=p_request->>'op'; token text:=p_request->>'token'; hash text; req_id text:=p_request->>'requestId'; payload jsonb:=p_request-'token'-'epoch'; r ml_private.rooms; before_r ml_private.rooms; prior ml_private.intakes; receipt ml_private.receipts; a integer; m jsonb; mid uuid; pname text:=btrim(p_request->>'name'); keyname text; next_code text; attempt integer; found_room boolean:=false; outcome jsonb; reply jsonb; command jsonb; res jsonb; changed boolean:=false;
begin
 perform ml_private.need(jsonb_typeof(p_request)='object' and octet_length(p_request::text)<=16384,'请求格式无效或过大');
 perform ml_private.need(jsonb_typeof(p_request->'op')='string' and jsonb_typeof(p_request->'token')='string' and jsonb_typeof(p_request->'name')='string','身份字段必须为字符串');
 perform ml_private.need(op in ('create','join','resume','view','heartbeat','offline','ready','mode','start','leave','game'),'未知房间操作');
 perform ml_private.need(not exists(select 1 from jsonb_object_keys(p_request) k where k not in ('op','token','requestId','name','code','roomId','epoch','ready','mode','roomRevision','matchId','revision','intent')),'请求含不允许的字段');
 perform ml_private.need(token ~ '^[a-f0-9]{64}$','恢复凭据无效'); hash:=ml_private.token_hash(token);
 perform ml_private.need(length(pname) between 1 and 24 and pname !~ '[[:cntrl:]]','玩家名须为1至24个可见字符'); keyname:=lower(pname);
 if op in ('create','join','ready','mode','start','leave','game') then perform ml_private.need(jsonb_typeof(p_request->'requestId')='string' and req_id ~ '^[A-Za-z0-9_-]{1,100}$','请求编号无效'); end if;
 if op in ('create','join') then
  -- Serializes identical uncertain intake retries before assigning any seat/code.
  perform pg_advisory_xact_lock(('x'||substr(hash,1,16))::bit(64)::bigint);
  select * into prior from ml_private.intakes i where i.token_hash=hash and i.request_id=req_id;
  if found then
   perform ml_private.need(prior.payload=payload,'同一请求编号不能更换内容');
   select * into r from ml_private.rooms where id=prior.room_id for update;
   perform ml_private.need(r.status<>'closed','原房间已关闭，凭据已失效');
   for a in 0..3 loop if r.members->a->>'id'=prior.member_id::text then
    r:=ml_private.refresh_room(r,at); perform ml_private.save_room(r);
    perform ml_private.need(r.status<>'closed' and r.members->a->>'id'=prior.member_id::text,'原座位已释放');
    return jsonb_build_object('ok',true,'duplicate',true,'snapshot',ml_private.room_view(r,a,at));
   end if; end loop; raise exception '原座位已释放';
  end if;
  perform ml_private.throttle('intake:'||hash,at,30);
  if op='create' then
   perform ml_private.throttle('create:global',at,120);
   for attempt in 1..200 loop
    next_code:=lpad(ml_private.entropy(10000)::text,4,'0');
    begin
     insert into ml_private.rooms(code,created_at,updated_at,members) values(next_code,at,at,'[null,null,null,null]') returning * into r; found_room:=true;
    exception when unique_violation then null; end;
    exit when found_room;
   end loop; perform ml_private.need(found_room,'可用房间码暂不足，请稍后重试'); a:=0;
  else
   perform ml_private.need(jsonb_typeof(p_request->'code')='string' and p_request->>'code' ~ '^[0-9]{4}$','房间码必须是4位数字');
   select * into r from ml_private.rooms where code=p_request->>'code' and status<>'closed' for update;
   perform ml_private.need(found,'房间不存在或已关闭'); r:=ml_private.refresh_room(r,at); perform ml_private.save_room(r);
   perform ml_private.need(r.status in ('lobby','finished'),'对局进行中，不能加入');
   perform ml_private.need(not exists(select 1 from ml_private.arr(r.members) x where x->>'key'=keyname),'该房间已有同名玩家，请使用原凭据恢复或换名');
   a:=null; for attempt in 0..3 loop if r.members->attempt='null'::jsonb then a:=attempt; exit; end if; end loop; perform ml_private.need(a is not null,'房间已满');
  end if;
  mid:=gen_random_uuid(); m:=jsonb_build_object('id',mid,'seat',a,'name',pname,'key',keyname,'tokenHash',hash,'ready',false,'lastSeen',at,'offlineSince',null,'joinedAt',at,'epoch',1);
  r.members:=jsonb_set(ml_private.clear_ready(r.members),array[a::text],m); r.host:=coalesce(r.host,mid); r.empty_since:=null; r.revision:=r.revision+1; r.updated_at:=at; perform ml_private.save_room(r);
  insert into ml_private.intakes values(hash,req_id,payload,r.id,mid,at);
  return jsonb_build_object('ok',true,'snapshot',ml_private.room_view(r,a,at));
 end if;
 perform ml_private.need(jsonb_typeof(p_request->'roomId')='string' and p_request->>'roomId' ~ '^[a-f0-9-]{36}$','房间身份无效');
 select * into r from ml_private.rooms where id=(p_request->>'roomId')::uuid for update;
 perform ml_private.need(found and r.status<>'closed','房间不存在或已关闭');
 r:=ml_private.refresh_room(r,at);
 a:=null; for attempt in 0..3 loop m:=r.members->attempt; if m->>'tokenHash'=hash and m->>'key'=keyname then a:=attempt; exit; end if; end loop;
 if a is null then
  perform ml_private.save_room(r);
  if op='leave' then
   select q.* into receipt from ml_private.receipts q join ml_private.intakes i on i.room_id=q.room_id and i.member_id=q.member_id where i.token_hash=hash and q.room_id=r.id and q.request_id=req_id limit 1;
   if found and receipt.payload=payload and receipt.outcome->>'left'='true' then return receipt.outcome||jsonb_build_object('duplicate',true); end if;
  end if;
  return jsonb_build_object('ok',false,'error','恢复凭据或玩家名不匹配，座位可能已释放');
 end if;
 m:=r.members->a; mid:=(m->>'id')::uuid;
 perform ml_private.throttle('member:'||mid,at,240);
 if op='resume' then m:=m||jsonb_build_object('epoch',(m->>'epoch')::bigint+1); else perform ml_private.need(jsonb_typeof(p_request->'epoch')='number' and p_request->'epoch'=m->'epoch','连接已被新页面接管，请停止重连'); end if;
 if op='offline' then m:=m||jsonb_build_object('offlineSince',at); if r.status in ('lobby','finished') then m:=m||jsonb_build_object('ready',false); r.revision:=r.revision+1; end if;
 else m:=m||jsonb_build_object('lastSeen',at,'offlineSince',null); end if;
 r.members:=jsonb_set(r.members,array[a::text],m);
 if op in ('resume','view','heartbeat','offline') then perform ml_private.save_room(r); return jsonb_build_object('ok',true,'snapshot',ml_private.room_view(r,a,at)); end if;
 select * into receipt from ml_private.receipts q where q.room_id=r.id and q.member_id=mid and q.request_id=req_id;
 if found then
  perform ml_private.save_room(r); if receipt.payload<>payload then return jsonb_build_object('ok',false,'error','同一请求编号不能更换内容','snapshot',ml_private.room_view(r,a,at)); end if;
  return receipt.outcome||jsonb_build_object('duplicate',true,'snapshot',ml_private.room_view(r,a,at));
 end if;
 -- Subtransaction catches rejected commands while preserving elapsed clock work.
 before_r:=r;
 begin
  if op in ('ready','mode','start','leave') then perform ml_private.need(jsonb_typeof(p_request->'roomRevision')='number' and p_request->'roomRevision'=to_jsonb(r.revision),'房间状态已更新，请查看后重试'); end if;
  if op='game' then
   perform ml_private.need(r.status='playing' and p_request->>'matchId'=r.match_id::text,'对局身份已过期');
   command:=p_request->'intent'; perform ml_private.need(jsonb_typeof(command)='object' and command->>'type' in ('play','move','step','stop','end','choose','location'),'操作意图无效');
   perform ml_private.need(not exists(select 1 from jsonb_object_keys(command) k where k not in ('type','card','targets','path','choice','accept','cell','cards','kind')),'操作含不允许的字段');
   command:=command||jsonb_build_object('actor',a,'revision',p_request->'revision','id',r.match_id::text||':'||mid::text||':'||req_id);
   res:=ml_private.dispatch(r.game,command,at); perform ml_private.need((res->>'ok')::boolean,res->>'error'); r.game:=res->'state'; changed:=true;
   if r.game->>'phase'='over' then r.status:='finished'; r.members:=ml_private.clear_ready(r.members); insert into ml_private.archives values(r.match_id,r.id,r.game,at+86400000) on conflict do nothing; end if;
  elsif op='ready' then
   perform ml_private.need(r.status in ('lobby','finished'),'对局进行中不能修改准备'); perform ml_private.need(jsonb_typeof(p_request->'ready')='boolean','准备状态无效'); r.members:=jsonb_set(r.members,array[a::text,'ready'],p_request->'ready'); changed:=true;
  elsif op='mode' then
   perform ml_private.need(r.host=mid and r.status in ('lobby','finished'),'只有房主可在开局前选择模式'); perform ml_private.need(p_request->>'mode' in ('ffa','team'),'模式无效'); r.mode:=p_request->>'mode'; r.members:=ml_private.clear_ready(r.members); changed:=true;
  elsif op='start' then
   perform ml_private.need(r.host=mid and r.status in ('lobby','finished'),'只有房主可开始新局');
   perform ml_private.need((select count(*) from ml_private.arr(r.members) x where ml_private.online(x,at) and (x->>'ready')::boolean)=4,'需要四人在线且全部准备');
   r.match_id:=gen_random_uuid(); r.game:=ml_private.create_game(jsonb_build_object('mode',r.mode,'seed',0,'seats','[0,1,2,3]'::jsonb,'secure',true),at); r.status:='playing'; r.members:=ml_private.clear_ready(r.members); changed:=true;
  elsif op='leave' then
   perform ml_private.need(r.status in ('lobby','finished'),'进行中不释放座位；关闭页面后仍按原时限推进'); r.members:=jsonb_set(ml_private.clear_ready(r.members),array[a::text],'null'); r.revision:=r.revision+1; r.updated_at:=at; r:=ml_private.refresh_room(r,at); perform ml_private.save_room(r); reply:=jsonb_build_object('ok',true,'left',true); insert into ml_private.receipts values(r.id,mid,req_id,payload,reply,at); return reply;
  end if;
  if changed then r.revision:=r.revision+1; r.updated_at:=at; end if;
  outcome:=jsonb_build_object('ok',true,'appliedRevision',r.game->'revision','matchId',r.match_id);
 exception when others then r:=before_r; outcome:=jsonb_build_object('ok',false,'error',case when sqlstate='P0001' then sqlerrm else '操作未提交，服务暂不可用' end);
 end;
 perform ml_private.save_room(r); insert into ml_private.receipts values(r.id,mid,req_id,payload,outcome,at);
 return outcome||jsonb_build_object('snapshot',ml_private.room_view(r,a,at));
exception when others then return jsonb_build_object('ok',false,'error',case when sqlstate='P0001' then sqlerrm else '请求无效或服务暂不可用' end);
end $$;
create or replace function public.ml_health() returns jsonb language sql security definer set search_path=pg_catalog as $$
 with readiness as (select coalesce((select value#>>'{manifest,status}'='playable' and jsonb_array_length(value#>'{runtimeData,allCards}')=64 and value#>>'{environment,kind}'='classic-regions-v1' and value#>>'{characterTraits,character-004,faction}'='帝汶家族' and value#>>'{characterTraits,character-004,spawnRegion}'='操场' from ml_private.catalog where key='ruleset:web-v0.1.4'),false) and to_regprocedure('ml_private.classic_walk(jsonb,jsonb,double precision)') is not null and to_regprocedure('ml_private.classic_environment(jsonb)') is not null as ready)
 select jsonb_build_object('ok',true,'schemaVersion',2,'engineRevision',12,'ruleVersion','web-v0.1.4','legacyRuleVersions',jsonb_build_array('web-v0.1.1','web-v0.1.2','web-v0.1.3'),'feedbackRulesReady',true,'versionedDataReady',(select count(*)=4 from ml_private.catalog where key like 'ruleset:web-v0.1.%'),'locationDataReady',ready,'locationRulesReady',ready,'waterRulesReady',ready,'environmentRulesReady',ready,'classicPlayable',ready,'classicRuleVersion','web-v0.1.4','engine','postgresql') from readiness $$;
revoke all on all functions in schema ml_private from public;
DO $$ declare r text; begin foreach r in array array['anon','authenticated'] loop execute format('revoke all on all functions in schema ml_private from %I',r);end loop;end $$;
